import 'package:flutter/material.dart';
import '../models/user_model.dart';
import '../services/api_service.dart';
import 'login_screen.dart';
import 'scan_screen.dart';
import 'history_screen.dart';

class DashboardScreen extends StatefulWidget { const DashboardScreen({super.key}); @override State<DashboardScreen> createState()=>_DashboardScreenState(); }
class _DashboardScreenState extends State<DashboardScreen> {
  UserModel? user; Map<String,dynamic>? today; bool loading=true;
  @override void initState(){super.initState();load();}
  Future<void> load() async { try { final me=await ApiService.me(); final td=await ApiService.today(); setState((){user=UserModel.fromJson(me['data']);today=td['data'];loading=false;}); } catch(e){ setState(()=>loading=false); if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ','')))); } }
  Future<void> logout() async { await ApiService.logout(); if(!mounted)return; Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder:(_)=>const LoginScreen()),(_)=>false); }
  @override Widget build(BuildContext context){ final s=user?.student; final hadir=today!=null; return Scaffold(appBar:AppBar(title:const Text('Dashboard',style:TextStyle(fontWeight:FontWeight.w800)),backgroundColor:Colors.transparent,actions:[IconButton(onPressed:logout,icon:const Icon(Icons.logout))]),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(18,8,18,30),children:[
    Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(borderRadius:BorderRadius.circular(22),gradient:const LinearGradient(colors:[Color(0xFF102D49),Color(0xFF0A1C30)]),border:Border.all(color:Color(0xFF214A68))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Halo,',style:TextStyle(color:Color(0xFF8EA9BF))),const SizedBox(height:4),Text(s?.nama??user?.name??'-',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:5),Text('${s?.nis??'-'}  •  ${s?.kelas??'-'}',style:const TextStyle(color:Color(0xFF86C9EE))),]),
    const SizedBox(height:14), Row(children:[Expanded(child:_StatusCard(hadir:hadir)),const SizedBox(width:12),Expanded(child:_InfoCard(title:'Kelas',value:s?.kelas??'-',icon:Icons.school_outlined))]),
    const SizedBox(height:18), const Text('Menu Siswa',style:TextStyle(fontSize:15,fontWeight:FontWeight.w800)), const SizedBox(height:10),
    Row(children:[Expanded(child:_MenuCard(icon:Icons.qr_code_scanner,title:'Scan QR',onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ScanScreen())).then((_){load();}))),const SizedBox(width:10),Expanded(child:_MenuCard(icon:Icons.history,title:'Riwayat',onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const HistoryScreen()))))]),
    const SizedBox(height:18), Container(padding:const EdgeInsets.all(17),decoration:BoxDecoration(color:const Color(0xFF0B1D31),borderRadius:BorderRadius.circular(18),border:Border.all(color:const Color(0xFF1B3D59))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Profil Siswa',style:TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:12),Text('Nama  : ${s?.nama??'-'}',style:const TextStyle(color:Color(0xFFA8BDCC))),Text('NIS   : ${s?.nis??'-'}',style:const TextStyle(color:Color(0xFFA8BDCC))),Text('Kelas : ${s?.kelas??'-'}',style:const TextStyle(color:Color(0xFFA8BDCC)))])
  ])); }
}
class _StatusCard extends StatelessWidget{final bool hadir;const _StatusCard({required this.hadir});@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFF0B1D31),borderRadius:BorderRadius.circular(18),border:Border.all(color:const Color(0xFF1B3D59))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(hadir?Icons.check_circle:Icons.schedule,color:hadir?const Color(0xFF6BD5A3):const Color(0xFFDEBE6F)),const SizedBox(height:10),const Text('Hari ini',style:TextStyle(color:Color(0xFF809AAF),fontSize:11)),const SizedBox(height:4),Text(hadir?'Sudah hadir':'Belum absen',style:const TextStyle(fontWeight:FontWeight.w800))]);}
class _InfoCard extends StatelessWidget{final String title,value;final IconData icon;const _InfoCard({required this.title,required this.value,required this.icon});@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(16),height:130,decoration:BoxDecoration(color:const Color(0xFF0B1D31),borderRadius:BorderRadius.circular(18),border:Border.all(color:const Color(0xFF1B3D59))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,color:const Color(0xFF72CFFF)),const Spacer(),Text(title,style:const TextStyle(color:Color(0xFF809AAF),fontSize:11)),const SizedBox(height:4),Text(value,style:const TextStyle(fontWeight:FontWeight.w800))]);}
class _MenuCard extends StatelessWidget{final IconData icon;final String title;final VoidCallback onTap;const _MenuCard({required this.icon,required this.title,required this.onTap});@override Widget build(BuildContext c)=>InkWell(onTap:onTap,borderRadius:BorderRadius.circular(18),child:Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:const Color(0xFF0B1D31),borderRadius:BorderRadius.circular(18),border:Border.all(color:const Color(0xFF1B3D59))),child:Column(children:[Icon(icon,size:30,color:const Color(0xFF70CBFF)),const SizedBox(height:10),Text(title,style:const TextStyle(fontWeight:FontWeight.w700))]));}
